from decimal import Decimal


def _to_decimal(val):
    if isinstance(val, float):
        val = str(val)
    return Decimal(val)


def line_total(qty, unit_price):
    q = _to_decimal(qty)
    p = _to_decimal(unit_price)
    result = q * p
    return result.quantize(Decimal("0.01"), rounding=decimal.ROUND_HALF_UP)


def invoice_total(lines, tax_rate):
    """lines is a list of (qty, unit_price) pairs; tax_rate like 0.08 for 8%."""
    subtotal = sum((line_total(q, p) for q, p in lines), Decimal("0.00"))
    t_rate = _to_decimal(tax_rate)
    total = subtotal * (Decimal("1") + t_rate)
    return total.quantize(Decimal("0.01"), rounding=decimal.ROUND_HALF_UP)
