def test_types_and_float_conversion():
    assert line_total(2, 1.5) == Decimal("3.00")
    assert line_total("2", "1.5") == Decimal("3.00")
    assert line_total(Decimal("2"), Decimal("1.5")) == Decimal("3.00")


def test_tax_rounding_at_end():
